import os, json, glob, collections, datetime, re, sys

root = os.path.expanduser("~/.claude/projects")
files = []
for f in glob.glob(os.path.join(root, "*", "*.jsonl")):
    try: files.append((os.path.getmtime(f), f))
    except OSError: pass
files.sort(reverse=True)
sel = files[:50]

mtimes = [t for t,_ in sel]
def d(ts): return datetime.datetime.utcfromtimestamp(ts).strftime("%Y-%m-%d")
print(f"WINDOW files={len(sel)} newest={d(max(mtimes))} oldest={d(min(mtimes))} span_days={round((max(mtimes)-min(mtimes))/86400,1)}")
projs = collections.Counter(os.path.basename(os.path.dirname(f)) for _,f in sel)
print("PROJECTS:", dict(projs))

mcp = collections.Counter()
skills = collections.Counter()
slash = collections.Counter()
hooks = collections.defaultdict(list)
hook_to = collections.Counter()
denials = collections.Counter()      # (pattern) -> count
denial_kind = collections.defaultdict(collections.Counter)
tooluse = {}   # id -> (name, input)
fallback_denials = collections.Counter()
tools_all = collections.Counter()

cmdre = re.compile(r"<command-name>/?([A-Za-z0-9:_\-]+)</command-name>")

for _, path in sel:
    try:
        fh = open(path, "r", encoding="utf-8", errors="replace")
    except OSError:
        continue
    with fh:
        for line in fh:
            if len(line) > 4_000_000: continue
            try: o = json.loads(line)
            except Exception: continue
            t = o.get("type")
            if t == "assistant":
                msg = o.get("message") or {}
                for c in (msg.get("content") or []):
                    if isinstance(c, dict) and c.get("type") == "tool_use":
                        nm = c.get("name") or ""
                        tools_all[nm] += 1
                        tid = c.get("id")
                        inp = c.get("input") or {}
                        if tid: tooluse[tid] = (nm, inp)
                        if nm.startswith("mcp__"): mcp[nm] += 1
                        elif nm == "Skill":
                            s = inp.get("skill") if isinstance(inp, dict) else None
                            if s: skills[str(s)] += 1
            elif t == "user":
                msg = o.get("message") or {}
                cont = msg.get("content")
                txt = ""
                if isinstance(cont, str): txt = cont
                elif isinstance(cont, list):
                    for c in cont:
                        if isinstance(c, dict):
                            if c.get("type") == "text": txt += c.get("text") or ""
                            elif c.get("type") == "tool_result":
                                dk = o.get("toolDenialKind")
                                tid = c.get("tool_use_id")
                                nm, inp = tooluse.get(tid, (None, None))
                                if dk and dk not in ("interrupted","cancelled"):
                                    if nm:
                                        if nm == "Bash":
                                            cmd = (inp or {}).get("command","") if isinstance(inp,dict) else ""
                                            parts = str(cmd).strip().split()
                                            key = "Bash:" + " ".join(parts[:2]) if parts else "Bash:?"
                                        else:
                                            key = nm
                                        denials[key] += 1
                                        denial_kind[key][dk] += 1
                                elif not dk:
                                    body = c.get("content")
                                    s = ""
                                    if isinstance(body, str): s = body
                                    elif isinstance(body, list):
                                        for b in body:
                                            if isinstance(b, dict) and b.get("type")=="text": s += b.get("text") or ""
                                    if c.get("is_error") and s and nm and not nm.startswith("mcp__"):
                                        if ("The user doesn't want to proceed with this tool use" in s
                                            or s.startswith("Permission to use") or s.startswith("Permission for this")):
                                            if nm == "Bash":
                                                cmd = (inp or {}).get("command","") if isinstance(inp,dict) else ""
                                                parts = str(cmd).strip().split()
                                                key = "Bash:" + " ".join(parts[:2]) if parts else "Bash:?"
                                            else: key = nm
                                            fallback_denials[key] += 1
                for m in cmdre.finditer(txt): slash[m.group(1)] += 1
            elif t == "attachment":
                a = o.get("attachment") or {}
                at = a.get("type") or ""
                if at.startswith("hook_"):
                    hn = str(a.get("hookName") or "?")
                    he = str(a.get("hookEvent") or "?")
                    dur = a.get("durationMs")
                    k = f"{hn}|{he}"
                    if isinstance(dur,(int,float)): hooks[k].append(dur)
                    if at == "hook_cancelled" and a.get("timedOut"):
                        hook_to[k] += 1

def top(c,n=40):
    return [f"{k}={v}" for k,v in c.most_common(n)]

print("\n=== MCP TOOL CALLS (by server) ===")
srv = collections.Counter()
for k,v in mcp.items():
    m = re.match(r"mcp__([^_].*?)__", k)
    srv[m.group(1) if m else k] += v
for k,v in srv.most_common(): print(f"  {k}\t{v}")

print("\n=== SKILL TOOL DISPATCHES ===")
for k,v in skills.most_common(60): print(f"  {k}\t{v}")

print("\n=== SLASH COMMANDS ===")
for k,v in slash.most_common(60): print(f"  {k}\t{v}")

print("\n=== HOOKS (n, p50ms, maxms, timeouts) ===")
for k,v in sorted(hooks.items(), key=lambda kv: -max(kv[1])):
    v2 = sorted(v)
    p50 = v2[len(v2)//2]
    print(f"  {k}\tn={len(v)}\tp50={int(p50)}\tmax={int(max(v))}\ttimeouts={hook_to.get(k,0)}")
for k,v in hook_to.items():
    if k not in hooks: print(f"  {k}\tn=0\ttimeouts={v}")

print("\n=== DENIALS (CLI-stamped) ===")
for k,v in denials.most_common(40): print(f"  {k}\t{v}\t{dict(denial_kind[k])}")
print("\n=== DENIALS (text fallback, unverified) ===")
for k,v in fallback_denials.most_common(40): print(f"  {k}\t{v}")

print("\n=== TOP TOOLS OVERALL ===")
for k,v in tools_all.most_common(25): print(f"  {k}\t{v}")
